    // W = Sum_{x=r}^{s} [ 
    //       (number of (a2..ap) with sum=s-x, all < x)   [Case 1: strictly best, weight 1]
    //       + Sum_{j=0}^{p-1} C(p-1, j) * (number of (remaining p-1-j vars) with sum = s-(j+1)*x, each <= x-1) * (1/(j+1))
