    // W = Sum_{x=r}^{s} Sum_{j=0}^{min(p-1, floor((s-x)/x))} C(p-1, j) * f(p-1-j, s-(j+1)*x, x-1) * inv(j+1)
    // where f(n, S, M) = number of non-negative integer solutions to y1+...+yn = S with each yi <= M.

    // And T = C(s - r + p - 1, p - 1)  [total number of states]

    // Then answer = W / T mod MOD.

    // However, note: the total number of states T is the number of non-negative solutions to a1+...+ap=s with a1>=r.
    // As said, T = C(s - r + p - 1, p - 1) if s >= r, else 0. But given r<=s.

    // Now, how to compute f(n, S, M)?
    // f(n, S, M) = number of non-negative solutions to y1+...+yn=S with yi<=M.
    // This is a classic stars and bars with upper bound.
    // f(n, S, M) = Sum_{k=0}^{floor(S/(M+1))} (-1)^k * C(n, k) * C(S - k*(M+1) + n - 1, n - 1)
    // But note: if S < 0, f=0. If M < 0 and S>0, f=0. If n==0, then f=1 if S==0 else 0.

    // However, n can be up to 99, S up to 5000, M up to 5000. The sum over k might be large but S/(M+1) is at most S, which is 5000, and n is at most 99, so it's acceptable.

    // But note: we need to compute binomial coefficients up to about 5000+100 = 5100.

    // Precompute factorials and inverse factorials up to N = 5000 + 100 + 10 = 5110.

    int N = 5110;
    vector<long long> fact(N+1), invfact(N+1);
    fact[0] = 1;
    for (int i = 1; i <= N; i++) {
        fact[i] = fact[i-1] * i % MOD;
    }
    invfact[N] = modinv(fact[N], MOD);
    for (int i = N-1; i >= 0; i--) {
        invfact[i] = invfact[i+1] * (i+1) % MOD;
    }

    auto C = [&](int n, int k) -> long long {
        if (k < 0 || k > n) return 0;
        return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD;
    };

    // f(n, S, M): number of non-negative solutions to y1+...+yn = S with each yi <= M.
    auto f = [&](int n, int S, int M) -> long long {
        if (S < 0) return 0;
        if (n == 0) {
            return S == 0 ? 1 : 0;
        }
        if (M < 0) {
            // if M < 0 and S > 0, no solution; if S==0 and n>0, but M<0 means each yi<=M<0, so only possible if S==0 and all yi=0, but 0<=M? No, M<0, so yi<=M<0, but yi>=0, so only possible if S==0 and n==0? But n>0 here. So return 0.
            return 0;
        }
        // If M is large enough that the upper bound doesn't matter, then it's just C(S+n-1, n-1).
        // But we'll use the inclusion-exclusion formula.
        long long res = 0;
        // k from 0 to min(n, S/(M+1))
        int max_k = min(n, S / (M+1));
        for (int k = 0; k <= max_k; k++) {
            long long term = C(n, k) * C(S - k*(M+1) + n - 1, n - 1) % MOD;
            if (k % 2 == 1) {
                res = (res - term + MOD) % MOD;
            } else {
                res = (res + term) % MOD;
            }
        }
        return res;
    };

    // Total number of states T
    long long T = 0;
    if (s >= r) {
        T = C(s - r + p - 1, p - 1);
    } else {
        T = 0;
    }

    // If T == 0, then no valid states? But r<=s, so T>=1.
    // Now compute W
    long long W = 0;
    for (int x = r; x <= s; x++) {
        // x is Hasan's score
        // j: number of other players who also score x
        // j from 0 to p-1
        for (int j = 0; j <= p-1; j++) {
