            // Multiply by 1/(j+1)
            long long inv_j1 = modinv(j+1, MOD);
            W = (W + ways * inv_j1) % MOD;
        }
    }

    // Answer = W * inv(T) mod MOD
    if (T == 0) {
        cout << 0 << endl;
    } else {
        long long ans = W * modinv(T, MOD) % MOD;
        cout << ans << endl;
    }

    return 0;
