int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, s, r;
    cin >> p >> s >> r;

    // We need to compute:
    // Total number of valid states: number of non-negative integer solutions to
    // a1 + a2 + ... + ap = s, where a1 >= r.
    // Let b1 = a1 - r >= 0, then b1 + a2 + ... + ap = s - r.
    // Number of solutions = C((s - r) + p - 1, p - 1) = C(s - r + p - 1, p - 1)
    //
    // Number of winning states: states where Hasan wins.
    // Hasan wins if he is the unique top scorer, or if there's a tie for top score, 
    // he wins with probability 1/(number of top scorers).
    //
    // Let's think about this differently. For each possible score x for Hasan (a1 = x),
    // where x >= r and x <= s, the remaining p-1 players have scores summing to s - x.
    // The number of ways to distribute s - x among p-1 players is C(s - x + p - 2, p - 2).
    //
