            long long inv = modinv(1 + t, MOD);
            B = (B + comb * ways % MOD * inv) % MOD;
        }

        numerator = (numerator + A + B) % MOD;
    }

    numerator = (numerator % MOD + MOD) % MOD;
    long long ans = numerator * modinv(total, MOD) % MOD;
    cout << ans << endl;

    return 0;
}
