// Number of non-negative integer solutions to x1 + x2 + ... + xk = n
// This is C(n + k - 1, k - 1)
long long stars_and_bars(long long n, long long k) {
    if (k == 0) {
        return (n == 0) ? 1 : 0;
    }
    // C(n + k - 1, k - 1)
    long long N = n + k - 1;
    long long R = k - 1;
    if (R < 0 || R > N) return 0;

    // Compute C(N, R) mod MOD
    // N can be up to 5000 + 100 - 1 = 5099, which is small enough
    // Precompute factorials up to 5100
    static vector<long long> fact(5100), invfact(5100);
    static bool initialized = false;
    if (!initialized) {
        fact[0] = 1;
        for (int i = 1; i < 5100; i++) {
            fact[i] = fact[i-1] * i % MOD;
        }
        invfact[5099] = modinv(fact[5099], MOD);
        for (int i = 5098; i >= 0; i--) {
            invfact[i] = invfact[i+1] * (i+1) % MOD;
        }
        initialized = true;
    }

    if (N >= 5100) return 0; // Should not happen given constraints

    long long res = fact[N] * invfact[R] % MOD * invfact[N - R] % MOD;
    return res;
}

