    // Then f(x, m, c) = C(m, c) * h(m-c, S - c*x, x)

    // And h(m, S, x) can be computed using DP or inclusion-exclusion.
    // h(m, S, x) = number of non-negative integer solutions to y1 + ... + ym = S with yi <= x-1.
    // This is C(S + m - 1, m - 1) - C(S - x + m - 1, m - 1) + ... (inclusion-exclusion)
    // But S can be up to 5000 and m up to 100, so we can precompute h for all needed values.

    // Actually, let's precompute a 2D DP:
    // h[m][S] = number of ways to assign m players scores in [0, x-1] summing to S.
    // But x varies, so we can't precompute for all x.

    // However, for fixed x, h depends on x. So we still need to compute it for each x.

    // Let's estimate the complexity again.
    // For each x (up to 5000), we need to compute h for m up to 100 and S up to 5000.
    // h can be computed with a DP: dp[i][j] = number of ways for i players, sum j, each in [0, x-1].
    // This DP is O(m * S) per x, so 100 * 5000 = 5e5 per x.
    // Total: 5000 * 5e5 = 2.5e9, which might be borderline in C++.

    // But we also need to sum over c, which is O(m) per x, so that's fine.

    // Let's try to implement this.

    long long numerator = 0;

    for (int x = r; x <= s; x++) {
        int S = s - x;
        if (S < 0) continue;

        // Compute h[m][j] for m = 0..p-1, j = 0..S
        // h[m][j] = number of ways to assign m players scores in [0, x-1] summing to j
        // If x == 0, then scores must be 0, so h[m][j] = 1 if j==0 and m>=0, else 0.
        // But x >= r >= 0, and if x==0, then S = s, and if s>0, no solutions.

        vector<vector<long long>> h(p, vector<long long>(S + 1, 0));
        h[0][0] = 1;
        for (int i = 1; i < p; i++) {
            for (int j = 0; j <= S; j++) {
                long long val = 0;
                // Score of player i can be 0 to min(x-1, j)
                int max_score = min(x - 1, j);
                for (int sc = 0; sc <= max_score; sc++) {
                    val = (val + h[i-1][j - sc]) % MOD;
                }
                h[i][j] = val;
            }
        }

        // Now for this x, sum over c = 0 to p-1:
        // C(p-1, c) * h[p-1-c][S - c*x] / (c+1)
        // But we need S - c*x >= 0, and p-1-c >= 0.

        for (int c = 0; c <= p - 1; c++) {
            int rem_players = p - 1 - c;
            int rem_sum = S - c * x;
            if (rem_sum < 0) continue;
            if (rem_players < 0) continue;
            if (rem_sum > S) continue;

            long long ways = C(p - 1, c) * h[rem_players][rem_sum] % MOD;
            long long inv_c1 = modinv(c + 1, MOD);
            numerator = (numerator + ways * inv_c1) % MOD;
        }
    }

    long long ans = numerator * modinv(total, MOD) % MOD;
    cout << ans << "\n";

    return 0;
