            if (players_left == 0) {
                if (rem == 0) ways = 1;
                else ways = 0;
            } else {
                for (int j = 0; j <= players_left; j++) {
                    int n_val = rem - j * x + players_left - 1;
                    int k_val = players_left - 1;
                    if (n_val < k_val) continue;
                    if (n_val < 0) continue;
                    long long term = C(players_left, j) * C(n_val, k_val) % MOD;
                    if (j % 2 == 0) {
                        ways = (ways + term) % MOD;
                    } else {
                        ways = (ways - term + MOD) % MOD;
                    }
                }
            }

            // Contribution: C(p-1, k) * ways * inv(k+1)
            long long comb = C(p-1, k);
            long long inv_k1 = modinv(k + 1, MOD);
            long long contrib = comb * ways % MOD * inv_k1 % MOD;
            numerator = (numerator + contrib) % MOD;
        }
    }

    // Probability = numerator / total
    long long ans = numerator * modinv(total, MOD) % MOD;
    cout << ans << endl;

    return 0;
}
