#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

long long modpow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

long long modinv(long long a, long long mod) {
    return modpow(a, mod - 2, mod);
}

// C(n, k) mod MOD
long long C(long long n, long long k) {
    if (k < 0 || k > n) return 0;
    // We need factorials up to n
    // Since s <= 5000 and p <= 100, n can be up to s + p - 1 <= 5099
    // Precompute factorials and inverse factorials up to 5100
    static bool init = false;
    static vector<long long> fact(5100), invfact(5100);
    if (!init) {
        fact[0] = 1;
        for (int i = 1; i < 5100; i++) fact[i] = fact[i-1] * i % MOD;
        invfact[5099] = modinv(fact[5099], MOD);
        for (int i = 5098; i >= 0; i--) invfact[i] = invfact[i+1] * (i+1) % MOD;
        init = true;
    }
    if (n >= 5100) return 0;
    return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, s, r;
    cin >> p >> s >> r;

    // Total number of states: number of non-negative integer solutions to
    // a1 + a2 + ... + ap = s with a1 >= r
    // Let b1 = a1 - r >= 0, then b1 + a2 + ... + ap = s - r
    // Number of solutions = C((s - r) + p - 1, p - 1) = C(s - r + p - 1, p - 1)

    long long total = C(s - r + p - 1, p - 1);

    // Number of favorable states: Hasan wins
    // Hasan wins if a1 > ai for all i >= 2, OR if a1 is tied for the maximum and he is randomly selected.
    // Actually, the problem says: "Winner is the one who scores the most. In case of ties, one of the top-scorers will be declared as the winner randomly with equal probability."
    // So for a given state (a1, a2, ..., ap), let M = max(a1, a2, ..., ap).
    // Let k = number of players with score M.
    // Hasan's probability of winning in this state is 1/k if a1 == M, else 0.

    // We need to sum over all valid states the probability of Hasan winning.
    // Total probability = (sum over all states of [1/k if a1 == M else 0]) / total

    // Let's compute the numerator: sum over all valid states of (1/k if a1 == M else 0)
    // This is tricky because k depends on the state.

    // Alternative approach:
    // For each possible value of a1 = x (where x >= r and x <= s), we can compute:
    // - The number of states where a1 = x and x is strictly greater than all other ai
    // - The number of states where a1 = x and x is equal to the maximum of the others (i.e., some other player also has x)

    // Let's denote:
    // For a fixed x = a1:
    //   The remaining p-1 players have scores a2, ..., ap such that a2 + ... + ap = s - x, and each ai >= 0.
    //   Let M' = max(a2, ..., ap).
    //   If x > M', then Hasan is the unique top scorer, so he wins with probability 1.
    //   If x == M', then the number of top scorers is 1 + (number of players among a2..ap with score x).
    //     Let j = number of players among a2..ap with score x.
    //     Then total top scorers = 1 + j.
    //     Hasan's win probability = 1/(1+j).

    // So we need to sum over x from r to s:
    //   [ (number of ways to assign a2..ap with sum s-x and max < x) * 1
    //     + sum over j>=1 of (number of ways to assign a2..ap with sum s-x, max = x, and exactly j players have score x) * 1/(1+j) ]

    // Let's define:
    //   f(n, m, max_val) = number of ways to assign n non-negative integers summing to m with each <= max_val
    //   But we need more specific counts.

    // Let's use generating functions or combinatorial counting.

    // For fixed x:
    //   Let rem = s - x. We need to count assignments of a2..ap (p-1 variables) summing to rem.
    //   
    //   Case 1: All ai < x for i=2..p.
    //     Number of ways = number of non-negative integer solutions to a2+...+ap = rem with each ai <= x-1.
    //     This is C(rem + p - 1, p - 1) - (number of solutions where at least one ai >= x).
    //     Using inclusion-exclusion:
    //     Let g(rem, p-1, x-1) = number of solutions to a2+...+ap = rem with each ai <= x-1.
    //     g(rem, n, K) = sum_{j=0}^{floor(rem/(K+1))} (-1)^j * C(n, j) * C(rem - j*(K+1) + n - 1, n - 1)
    //     Here n = p-1, K = x-1.
    //     
    //   Case 2: Some ai = x.
    //     Let j = number of players among a2..ap with score exactly x.
    //     For a fixed j (1 <= j <= p-1), and j <= rem/x:
    //       Choose which j players have score x: C(p-1, j)
    //       The remaining (p-1-j) players have scores summing to rem - j*x, each <= x-1 (since if any were >= x, they'd be counted in a higher j, but we're fixing exactly j players with score x, so the others must be < x).
    //       Wait, actually the others must be <= x-1 to ensure that exactly j players have score x.
    //       Number of ways for the remaining = g(rem - j*x, p-1-j, x-1)
    //     So for fixed x and j, the contribution is C(p-1, j) * g(rem - j*x, p-1-j, x-1) * 1/(1+j)

    // Let's implement g(rem, n, K):
    //   g(rem, n, K) = number of non-negative integer solutions to x1+...+xn = rem with each xi <= K.
    //   If rem < 0 or n < 0, return 0.
    //   If K < 0, return 0 (unless rem==0 and n==0, but let's handle carefully).
    //   Using inclusion-exclusion:
    //   g(rem, n, K) = sum_{j=0}^{min(n, rem/(K+1))} (-1)^j * C(n, j) * C(rem - j*(K+1) + n - 1, n - 1)
    //   Note: C(rem - j*(K+1) + n - 1, n - 1) is 0 if rem - j*(K+1) < 0.

    auto g = [&](int rem, int n, int K) -> long long {
        if (rem < 0 || n < 0) return 0;
        if (K < 0) {
            if (rem == 0 && n == 0) return 1;
            return 0;
        }
        long long res = 0;
        int maxj = min(n, rem / (K + 1));
        for (int j = 0; j <= maxj; j++) {
            long long term = C(n, j) * C(rem - j * (K + 1) + n - 1, n - 1) % MOD;
            if (j % 2 == 1) {
                res = (res - term + MOD) % MOD;
            } else {
                res = (res + term) % MOD;
            }
        }
        return res;
    };

    long long numerator = 0;
    for (int x = r; x <= s; x++) {
        int rem = s - x;
        int n = p - 1;
        int K = x - 1;

        // Case 1: all other players < x
        if (n == 0) {
            // p = 1, Hasan is the only player, he always wins
            numerator = (numerator + 1) % MOD;
            continue;
        }
        long long case1 = g(rem, n, K);
        numerator = (numerator + case1) % MOD;

        // Case 2: some players have score exactly x
        for (int j = 1; j <= n; j++) {
            if (j * x > rem) break;
            int rem2 = rem - j * x;
            int n2 = n - j;
            long long ways = C(n, j) * g(rem2, n2, K) % MOD;
            // Multiply by 1/(1+j)
            long long inv = modinv(1 + j, MOD);
            long long contrib = ways * inv % MOD;
            numerator = (numerator + contrib) % MOD;
        }
    }

    // Probability = numerator / total
    long long ans = numerator * modinv(total, MOD) % MOD;
    cout << ans << "\n";

    return 0;
}
